INSERT OR IGNORE INTO settings (key,value) VALUES ('hero_slogan','Господарський підхід до кожного двору Солом’янки: житлово-комунальне господарство, енергетика, робота зі зверненнями мешканців.');
INSERT OR IGNORE INTO settings (key,value) VALUES ('hero_photo','/img/deputy.jpg');
INSERT OR IGNORE INTO settings (key,value) VALUES ('logo','/img/logo-placeholder.svg');
INSERT OR IGNORE INTO settings (key,value) VALUES ('bio','Юрій Станіславович Тихонович — депутат Київської міської ради IX скликання від округу №12 (Солом’янський район), перший заступник голови постійної комісії з питань житлово-комунального господарства та паливно-енергетичного комплексу, член правління ПрАТ «ХК «Київміськбуд» і генеральний директор Медичного науково-практичного об’єднання «Медбуд».

Народився 21 червня 1970 року в Києві. Кандидат юридичних наук, інженер-будівельник. Понад два десятиліття професійно працює у сфері міського будівництва та житлово-комунального господарства столиці.');
INSERT OR IGNORE INTO settings (key,value) VALUES ('education','2015 — Київський національний університет імені Тараса Шевченка, науковий ступінь кандидата юридичних наук.
2011 — Київський національний університет будівництва і архітектури, спеціальність «Міське будівництво та господарство» (інженер-будівельник).
2007 — Київський славістичний університет, спеціальність «Менеджмент організацій».');
INSERT OR IGNORE INTO settings (key,value) VALUES ('career','з 2020 — заступник директора ТОВ «АЙ СІ ТІ»; член правління ПрАТ «ХК «Київміськбуд».
2013 — засновник ТОВ «ІБК «Столиця майбутнього».
2011 — засновник ТОВ «ІБК «Альянс капітал».
2006–2008 — заступник директора ВБК «Компроміс-ТВ».
2005–2007 — помічник-консультант народних депутатів України.
2004–2006 — заступник директора КП «Інженерний центр» КМДА.');
INSERT OR IGNORE INTO settings (key,value) VALUES ('activity_district','Округ №12, Солом’янський район м. Києва');
INSERT OR IGNORE INTO settings (key,value) VALUES ('activity_position','Перший заступник голови постійної комісії Київради з питань житлово-комунального господарства та паливно-енергетичного комплексу');
INSERT OR IGNORE INTO settings (key,value) VALUES ('activity_intro','Основні напрямки роботи — модернізація житлово-комунального господарства, надійність тепло- та енергопостачання, благоустрій і розвиток інфраструктури Солом’янського району.');
